const $=s=>document.querySelector(s), key='shixin-v1';
let config={mode:'month',salary:10000,days:22,hours:8,period:8}, session=null, hidden=false;
try{const saved=JSON.parse(localStorage.getItem(key));if(saved){config={...config,...saved.config};session=saved.session||null;hidden=!!saved.hidden;}}catch{}
const rate=c=>c.salary/(c.mode==='month'?c.days*c.hours*3600:c.mode==='hour'?3600:c.period*3600);
const persist=()=>{try{localStorage.setItem(key,JSON.stringify({config,session,hidden}));}catch{notify('浏览器无法保存数据，请保持页面打开。');}};
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function elapsed(now=Date.now()){if(!session)return 0;return session.accumulated+(session.state==='running'?Math.max(0,Math.min(now,session.autoEnd||Infinity)-session.segment):0)}
function date(t){return new Date(t).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false})}
function duration(ms){const s=Math.floor(ms/1000);return [Math.floor(s/3600),Math.floor(s/60)%60,s%60].map(x=>String(x).padStart(2,'0'))}
function current(){return session?session.config:config}
function setForm(){for(const n of ['salary','days','hours','period'])$('#'+n).value=config[n];document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===config.mode));$('#month-fields').hidden=config.mode!=='month';$('#period-fields').hidden=config.mode!=='period';$('#salary-label').textContent=config.mode==='month'?'每月薪资':config.mode==='hour'?'每小时薪资':'这段时间的收入';$('#days').required=$('#hours').required=config.mode==='month';$('#period').required=config.mode==='period'}
function render(){const c=current(),r=rate(c);if(session&&session.state!=='finished'&&session.autoEnd&&Date.now()>=session.autoEnd){end(true);return}const ms=elapsed(),amount=ms/1000*r;const parts=amount.toLocaleString('en-US',{minimumFractionDigits:4,maximumFractionDigits:4}).split('.');$('#money').innerHTML=hidden?'••••<span class="decimal">.••••</span>':parts[0]+'<span class="decimal">.'+parts[1]+'</span>';const d=duration(ms);$('#duration').innerHTML=`${d[0]}<span>时</span> ${d[1]}<span>分</span> ${d[2]}<span>秒</span>`;$('#second').textContent=hidden?'¥••••':'¥'+r.toFixed(4);$('#minute').textContent=hidden?'¥••••':'¥'+(r*60).toFixed(2);$('#hour').textContent=hidden?'¥••••':'¥'+(r*3600).toFixed(2);$('#formula').textContent=c.mode==='month'?`计算口径：月薪 ÷ ${c.days} 天 ÷ ${c.hours} 小时 ÷ 3,600 秒。仅计算工作时间。`:c.mode==='hour'?'计算口径：时薪 ÷ 3,600 秒。':`计算口径：时段收入 ÷ ${c.period} 小时 ÷ 3,600 秒。`;$('#started').textContent=session?date(session.started):'等待开始';const state=session?.state;$('#live').classList.toggle('running',state==='running');$('#start').textContent=state==='running'?'Ⅱ 暂停一下':state==='paused'?'▶ 继续积累':state==='finished'?'↻ 开始新的一次':'▶ 开始积累';$('#finish').disabled=!session||state==='finished';$('#hint').textContent=state==='running'?'正在记录你的付出，切到后台也能继续累计。':state==='paused'?'好好休息一下，暂停期间不会累计收入。':state==='finished'?'这一段付出已记录，愿接下来的时间也属于你。':'';$('#hint').hidden=!$('#hint').textContent;$('#form').querySelectorAll('input,button,summary').forEach(e=>{if(e.tagName!=='SUMMARY')e.disabled=!!session&&state!=='finished'});}
function readConfig(){return{mode:config.mode,salary:+$('#salary').value,days:+$('#days').value,hours:+$('#hours').value,period:+$('#period').value}}
function valid(c){return Number.isFinite(rate(c))&&rate(c)>0&&c.salary<=1e9&&(c.mode!=='month'||c.days>=1&&c.days<=31&&c.hours>=.1&&c.hours<=24)&&(c.mode!=='period'||c.period>0)}
function saveSettings(){if(!$('#form').reportValidity())return false;const c=readConfig();if(!valid(c)){$('#error').textContent='请输入有效的收入和工作时长。';return false}config=c;$('#error').textContent='';persist();render();return true}
$('#form').addEventListener('submit',e=>{e.preventDefault();if(saveSettings())notify('已更新你的时间价值。')});
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(session&&session.state!=='finished')return;config.mode=b.dataset.mode;setForm()});
function startNewSession({useSchedule=true}={}){
  if(!saveSettings())return false;
  const now=Date.now();
  const begin=useSchedule&&$('#begin').value?new Date($('#begin').value).getTime():now;
  const stop=useSchedule&&$('#stop').value?new Date($('#stop').value).getTime():null;
  if(!Number.isFinite(begin)||begin>now){$('#error').textContent='开始时间不能晚于现在。';return false}
  if(stop&&(!Number.isFinite(stop)||stop<=now||stop<=begin)){$('#error').textContent='自动结束时间需要晚于现在及开始时间。';return false}
  if(!useSchedule)$('#begin').value=$('#stop').value='';
  session={config:{...config},started:begin,segment:begin,accumulated:0,state:'running',autoEnd:stop,ended:null};
  persist();render();return true;
}
$('#start').onclick=()=>{
  if(session?.state==='running'){session.accumulated=elapsed();session.state='paused';persist();render();return}
  if(session?.state==='paused'){session.segment=Date.now();session.state='running';persist();render();return}
  startNewSession({useSchedule:!session});
};
function end(auto=false){if(!session||session.state==='finished')return;session.accumulated=elapsed();session.ended=auto?session.autoEnd:Date.now();session.state='finished';persist();render();showResult()}
$('#finish').onclick=()=>end();function showResult(){const d=duration(elapsed()),amount=elapsed()/1000*rate(session.config);$('#result-money').textContent=hidden?'¥ ••••':'¥ '+amount.toFixed(2);$('#result-time').textContent=`已工作 ${d[0]} 小时 ${d[1]} 分钟 ${d[2]} 秒`;$('#result-started').textContent=date(session.started);$('#result-ended').textContent=date(session.ended);const span=session.ended-session.started,paused=Math.max(0,span-elapsed());const format=ms=>{const t=duration(ms);return `${t[0]} 时 ${t[1]} 分 ${t[2]} 秒`};$('#result-span').textContent=`时间跨度 ${format(span)}`+(paused>=1000?` · 其中暂停 ${format(paused)}`:'');if(!$('#result').open)$('#result').showModal()}
$('.close').onclick=()=>$('#result').close();$('#discard').onclick=()=>$('#result').close();$('#new').onclick=()=>{if(startNewSession({useSchedule:false}))$('#result').close()};$('#hide').onclick=()=>{hidden=!hidden;$('#hide').setAttribute('aria-label',hidden?'显示金额':'隐藏金额');persist();render()};$('#privacy').onclick=()=>notify('薪资和计时记录仅保存在当前浏览器；清除浏览器数据后会丢失。');$('#clear').onclick=()=>{if(confirm('清除薪资设置和当前计时记录？此操作无法撤销。')){session=null;config={mode:'month',salary:10000,days:22,hours:8,period:8};hidden=false;try{localStorage.removeItem(key)}catch{}$('#begin').value=$('#stop').value='';setForm();render();notify('本机记录已清除。')}};
$('#download').onclick=()=>{const c=document.createElement('canvas');c.width=1080;c.height=1350;const x=c.getContext('2d');x.fillStyle='#f5f6f0';x.fillRect(0,0,1080,1350);x.fillStyle='#396848';x.font='36px sans-serif';x.fillText('◷ 时薪 · 看见时间的价值',80,120);x.fillStyle='#fff';x.beginPath();x.roundRect(60,250,960,750,36);x.fill();x.fillStyle='#859087';x.font='28px sans-serif';x.fillText('这份付出，值得记录。',110,340);x.fillStyle='#263d32';x.font='86px sans-serif';x.fillText($('#result-money').textContent,110,530);x.font='32px sans-serif';x.fillText($('#result-time').textContent,110,660);x.font='25px sans-serif';x.fillStyle='#859087';x.fillText(date(session.started)+' 开始',110,770);x.fillText(date(session.ended)+' 结束',110,820);x.font='32px sans-serif';x.fillStyle='#396848';x.fillText('工作有价值，休息也是。',80,1120);x.fillStyle='#859087';x.font='24px sans-serif';x.fillText('按实际工作时长估算 · 实际薪资以结算为准',80,1190);c.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='我的时间收获.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);notify('收获卡片已生成。')})};
setForm();render();setInterval(render,100);document.addEventListener('visibilitychange',()=>render());
